def generate_recommendations(project: dict, budget: dict, risk: dict, prediction: dict) -> list[dict]:
    recommendations=[]
    if project["delayed_milestones"] or prediction["delay_probability"] >= 35: recommendations.append({"title":"Increase delivery review cadence","reason":"Schedule variance and delayed milestone signals require active recovery governance.","priority":"High","suggested_action":"Run a weekly critical-path review and assign recovery owners.","expected_impact":"Improves schedule visibility and can recover 7-12 days.","confidence_score":91})
    if budget["budget_utilization_percent"] >= 90: recommendations.append({"title":"Initiate financial control review","reason":"Budget utilization exceeds the prescribed early-warning threshold.","priority":"High","suggested_action":"Freeze non-critical commitments and review supplier forecasts.","expected_impact":"Reduces projected cost variance.","confidence_score":92})
    if risk["high_risk_count"]: recommendations.append({"title":"Escalate risk mitigation","reason":"High-severity dependencies remain open in the project risk register.","priority":"High","suggested_action":"Assign command-level owners to mitigation actions and review closure weekly.","expected_impact":"Reduces critical path exposure.","confidence_score":94})
    if project["health_score"] >= 80: recommendations.append({"title":"Maintain current execution controls","reason":"Current health, financial, and schedule indicators remain within tolerance.","priority":"Low","suggested_action":"Continue approved controls and monthly portfolio reporting.","expected_impact":"Sustains mission readiness.","confidence_score":84})
    return recommendations
def build_summary(project: dict, budget: dict, prediction: dict, risk: dict) -> str:
    return f"{project['project_name']} is assessed as {project['health_status'].lower()} with a health score of {project['health_score']}/100. Budget utilization is {budget['budget_utilization_percent']}% and schedule status is {project['schedule_status'].lower()}. Overall risk is {risk['risk_level'].lower()}; forecast mission readiness is {prediction['mission_readiness_score']}%."
